/**
 * Jina AI Node - Version 1
 * Discriminator: resource=research, operation=deepResearch
 */


interface Credentials {
  jinaAiApi: CredentialReference;
}

/** Research a topic and generate a structured research report */
export type JinaAiV1ResearchDeepResearchParams = {
  resource: 'research';
  operation: 'deepResearch';
/**
 * The topic or question for the AI to research
 */
    researchQuery: string | Expression<string>;
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @default true
 */
    simplify?: boolean | Expression<boolean>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** The maximum number of URLs to include in the final answer
     */
    maxReturnedSources?: number | Expression<number>;
    /** A list of domains that are given a higher priority for content retrieval
     */
    prioritizeSources?: string | Expression<string>;
    /** A list of domains to be strictly excluded from content retrieval
     */
    excludeSources?: string | Expression<string>;
    /** Restrict search to specific websites
     */
    siteFilter?: string | Expression<string>;
  };
  requestOptions?: {
    /** Batching
     * @default {"batch":{}}
     */
    batching?: {
        /** Batching
     */
    batch?: {
      /** Input will be split in batches to throttle requests. -1 for disabled. 0 will be treated as 1.
       * @default 50
       */
      batchSize?: number | Expression<number>;
      /** Time (in milliseconds) between each batch of requests. 0 for disabled.
       * @default 1000
       */
      batchInterval?: number | Expression<number>;
    };
  };
    /** Whether to accept the response even if SSL certificate validation is not possible
     * @default false
     */
    allowUnauthorizedCerts?: boolean;
    /** HTTP proxy to use. If authentication is required it can be defined as follow: http://username:password@myproxy:3128
     */
    proxy?: string | Expression<string>;
    /** Time in ms to wait for the server to send response headers (and start the response body) before aborting the request
     * @default 10000
     */
    timeout?: number | Expression<number>;
  };
};

export type JinaAiV1ResearchDeepResearchOutput = {
  annotations?: Array<{
    type?: string;
    url_citation?: {
      dateTime?: string;
      exactQuote?: string;
      title?: string;
      url?: string;
    };
  }>;
  content?: string;
  usage?: {
    completion_tokens?: number;
    prompt_tokens?: number;
    total_tokens?: number;
  };
};

export type JinaAiV1ResearchDeepResearchNode = {
  type: 'n8n-nodes-base.jinaAi';
  version: 1;
  config: NodeConfig<JinaAiV1ResearchDeepResearchParams> & { credentials?: Credentials };
  output?: Items<JinaAiV1ResearchDeepResearchOutput>;
};